const input = $json.body ?? $json;
const text = (v) => v === null || v === undefined ? '' : String(v).trim();
const bool = (v) => typeof v === 'boolean' ? v : ['true','1','yes','on'].includes(text(v).toLowerCase());
const parse = (v, fallback) => {
  if (typeof v === 'string') {
    try { return JSON.parse(v || JSON.stringify(fallback)); } catch { return null; }
  }
  return v ?? fallback;
};

const action = text(input.action || 'create_text_document').toLowerCase();
const clinic_name = text(input.clinic_name);
const document_id = Number(input.document_id ?? 0);
const title = text(input.title);
const source_type = text(input.source_type || 'manual_text').toLowerCase();
const original_filename = text(input.original_filename);
const mime_type = text(input.mime_type);
const specialty = text(input.specialty || 'general').toLowerCase();
const topic = text(input.topic);
const service_name = text(input.service_name);
const version_label = text(input.version_label || '1.0');
const source_priority = Number(input.source_priority ?? 50);
const allowed_use = text(input.allowed_use || 'patient_information').toLowerCase();
const raw_text = text(input.raw_text);
const approved_by = text(input.approved_by);
const confirm_action = bool(input.confirm_action);

let qa_items = parse(input.qa_items, []);
let response_policy = parse(input.response_policy, {});
let metadata = parse(input.metadata, {});

const errors = [];
const actions = ['create_text_document','create_qa_document','publish','archive','list'];
const sources = ['pdf','docx','txt','html','manual_text','qa','other'];
const uses = ['patient_information','pre_visit_guidance','post_visit_guidance','clinical_information','internal_only'];

if (!actions.includes(action)) errors.push({field:'action',message:'اقدام معتبر نیست.'});
if (!clinic_name) errors.push({field:'clinic_name',message:'نام کلینیک الزامی است.'});
if (['publish','archive'].includes(action) && (!Number.isInteger(document_id) || document_id < 1)) {
  errors.push({field:'document_id',message:'شناسه سند الزامی است.'});
}
if (['create_text_document','create_qa_document'].includes(action) && !title) {
  errors.push({field:'title',message:'عنوان سند الزامی است.'});
}
if (!sources.includes(source_type)) errors.push({field:'source_type',message:'نوع منبع معتبر نیست.'});
if (!Number.isInteger(source_priority) || source_priority < 1 || source_priority > 100) {
  errors.push({field:'source_priority',message:'اولویت منبع باید بین 1 و 100 باشد.'});
}
if (!uses.includes(allowed_use)) errors.push({field:'allowed_use',message:'نوع استفاده معتبر نیست.'});
if (action === 'create_text_document' && raw_text.length < 20) {
  errors.push({field:'raw_text',message:'متن سند باید حداقل 20 کاراکتر باشد.'});
}
if (action === 'create_qa_document' && (!Array.isArray(qa_items) || qa_items.length < 1 || qa_items.length > 2000)) {
  errors.push({field:'qa_items',message:'qa_items باید آرایه‌ای با 1 تا 2000 مورد باشد.'});
}
if (!Array.isArray(qa_items)) qa_items = [];
if (!response_policy || Array.isArray(response_policy) || typeof response_policy !== 'object') {
  errors.push({field:'response_policy',message:'response_policy باید شیء JSON باشد.'});
  response_policy = {};
}
if (!metadata || Array.isArray(metadata) || typeof metadata !== 'object') {
  errors.push({field:'metadata',message:'metadata باید شیء JSON باشد.'});
  metadata = {};
}
if (action === 'publish' && !approved_by) {
  errors.push({field:'approved_by',message:'نام تأییدکننده برای انتشار الزامی است.'});
}
if (action !== 'list' && confirm_action !== true) {
  errors.push({field:'confirm_action',message:'عملیات باید تأیید شود.'});
}

return [{json:{
  action,clinic_name,document_id,title,source_type,original_filename,mime_type,
  specialty,topic,service_name,version_label,source_priority,allowed_use,raw_text,
  qa_items_json:JSON.stringify(qa_items),
  response_policy_json:JSON.stringify(response_policy),
  metadata_json:JSON.stringify(metadata),
  approved_by,confirm_action,
  validation_status:errors.length?'invalid':'valid',errors
}}];
